// ===== Font del gioco (incorporati, funzionano anche offline e da file://) =====
// Black Ops One (titoli) e Teko (interfaccia) — Google Fonts, licenza SIL Open Font License 1.1.
'use strict';
(function () {
  if (typeof FontFace === 'undefined' || !document.fonts) return;
  const add = (name, b64, desc) => { try { const f = new FontFace(name, 'url(data:font/woff2;base64,' + b64 + ')', desc); document.fonts.add(f); f.load().catch(() => { }); } catch (e) { } };
  add('Black Ops One', '', { weight: '400' });
  add('Teko', '', { weight: '300 700' });
})();
